style.css:
@-moz-document domain("roblox.com") {
body {
    background: url("https://i.imgur.com/duXfL6N.jpeg") no-repeat center center fixed !important;
    background-size: cover !important;
    color: #ff4d4d !important;
  }

  .navbar, .game-card-container, .section, .container, .content, .header, .footer, .game-carousel, .games-list-container, .game-card {
    background-color: rgba(0, 0, 0, 0.6) !important;
    border: none !important;
  }

  .text-label, a, .text-link {
    color: #ff4d4d !important;
  }

  .btn-primary {
    background-color: #cc0000 !important;
    border-color: #990000 !important;
  }

  .btn-primary:hover {
    background-color: #ff1a1a !important;
    border-color: #cc0000 !important;
  }

  * {
    box-shadow: none !important;
  }
}
